function exponentiationRapide(x, n) {
  if (n === 0) return 1;
  let result = 1;
  let base = x;
  while (n > 0) {
    if (n % 2 === 1) {
      result *= base;
    }
    base *= base;
    n = Math.floor(n / 2);
  }
  return result;
}
